import{_ as m}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as v,a as g,b as s,c as h,d as b,e as f,f as A,g as z,h as x,i as S,j as y}from"./chunks/M-SNOj.BjML9gyj.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as o}from"./chunks/OFF.BrU7kQE-.js";import{_ as l}from"./chunks/ON.DXVlsWbj.js";import{_ as n}from"./chunks/BDM.scaBLLhv.js";import{_ as q,C as L,o as P,c as _,a3 as r,j as t,a as p,E as c,w as u}from"./chunks/framework.g9mfNVRQ.js";const $=JSON.parse('{"title":"Allarmi e Avvisi","description":"","frontmatter":{"source_hash":"2ef67c25aa","source_commit":"8f65827","i18n_outdated":true},"headers":[],"relativePath":"it/use/alarms.md","filePath":"it/use/alarms.md"}'),I={name:"it/use/alarms.md"},k={class:"admonition xdrip"},R={style:{"background-color":"dimgray",color:"white","text-align":"center"}};function T(D,a,V,E,O,w){const d=L("big");return P(),_("div",null,[a[3]||(a[3]=r('<div class="admonition xdrip"><p class="admonition-title"><img src="'+m+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_add_alert_grey600_48dp.png" style="width:5%;"> Allarmi e Avvisi</p></div><p>Con xDrip puoi configurare molti avvisi.</p><p>Se xDrip è la tua unica app di monitoraggio della glicemia, ti consigliamo di attivare almeno tre avvisi:</p><ul><li>Avviso di glicemia bassa</li><li>Avviso di glicemia alta</li><li>Avviso di letture mancanti</li></ul><h3 id="glucose-level-alerts-list" tabindex="-1">Lista Allarmi Livello Glicemia <a class="header-anchor" href="#glucose-level-alerts-list" aria-label="Permalink to &quot;Lista Allarmi Livello Glicemia {#glucose-level-alerts-list}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Lista Allarmi Livello Glicemia</p></div><p>Per impostazione predefinita sono definiti un avviso di glicemia bassa e uno di glicemia alta.</p><p>Gli avvisi di glicemia bassa scattano quando la glicemia è uguale o inferiore al valore dell&#39;avviso, quelli di glicemia alta quando è uguale o superiore.</p><p>Per creare un nuovo avviso, tocca la barra del titolo <code>CREA ALLARME PER VALORE BASSO</code> o <code>ALTO</code>.</p><p>Per modificare un avviso esistente, fai un tocco prolungato sull&#39;avviso</p><div class="admonition xdrip"><p class="admonition-title">☰ Lista Allarmi</p><div style="background-color:gray;color:white;text-align:center;">  CREA ALLARME PER VALORE BASSO </div><p><small>  Allarme Valore BASSO       70      Tutto il giorno</small><br><small>Ignora la modalità silenziosa   Suoneria predefinita (suoneria sconosciuta)</small></p><div style="background-color:gray;color:white;text-align:center;">  CREA ALLARME PER VALORE ALTO </div><small>  Allarme Valore ALTO       224      Tutto il giorno</small><small>Ignora la modalità silenziosa   Suoneria predefinita (suoneria sconosciuta)</small></div><ol><li>Puoi dare all&#39;avviso il nome che vuoi, purché nessun altro avviso abbia lo stesso nome</li><li>La soglia è il livello di glicemia che fa scattare l&#39;allarme; un solo allarme può usare questo valore</li><li>La sospensione predefinita è il ritardo che ti verrà proposto quando sospendi l&#39;allarme</li><li>L&#39;allarme scatterà di nuovo ogni x minuti se non viene confermato</li></ol><div class="admonition xdrip"><p class="admonition-title">☰ Modifica Allarme</p><p>   Modifica Allarme Valore BASSO</p><p>  <small>Nome Allarme: <u>Allarme Valore BASSO</u></small> <span style="background-color:green;color:white;text-align:center;">1</span><br>   <small>Soglia: <u>70</u></small> <span style="background-color:green;color:white;text-align:center;">2</span><br>   <small>Sospensione Allarmi di Default: <u>35</u></small> <span style="background-color:green;color:white;text-align:center;">3</span><br>   <small>Riattiva Allarme ogni x min.: <u>1</u></small> <span style="background-color:green;color:white;text-align:center;">4</span><br>   <small>se non Riconosciuto</small></p><p>  <small>Tono Allarme: <u>Suoneria predefinita (suoneria sconosciuta)</u></small> <span style="background-color:green;color:white;text-align:center;">5</span></p></div><p> 5. Puoi personalizzare il suono dell&#39;avviso: tocca SCEGLI FILE per selezionare la suoneria di questo allarme.</p><ul><li><p>Suono/Allarme di Sistema ti permette di scegliere tra le suonerie del telefono.</p></li><li><p>Suono/Allarme Personalizzato ti permette di scegliere il tuo suono o la tua musica.</p></li><li><p>Suono xDrip predefinito usa il suono predefinito dell&#39;app.</p></li></ul><div class="admonition xdripitem"><p class="admonition-title">Che tipo di suono?</p><p> Suono/Allarme di Sistema<br>  Suono/Allarme Personalizzato<br>  Suono xDrip predefinito</p></div><p>Per impostazione predefinita l&#39;allarme è attivo per tutto il giorno.</p><div class="admonition xdripitem"><p class="admonition-title"><small>Seleziona Tono Allarme:</small></p><p>         ✅ Tutto il giorno</p></div><p>Se togli la spunta, puoi personalizzare gli orari di attività.<br> Tocca l&#39;ora di inizio e l&#39;ora di fine per definire da che ora a che ora l&#39;allarme sarà attivo.</p><div class="admonition xdripitem"><p class="admonition-title"><small>Seleziona Tono Allarme:</small></p><p>         ☐ Tutto il giorno<br>         0:00 - 0:00</p></div><p>Puoi disattivare l&#39;allarme (togliendo la spunta) quando il telefono è in modalità silenziosa (disattivarlo è sconsigliato)</p><div class="admonition xdripitem"><p class="admonition-title"><small>Perrmetti ALLARMI anche in Modo Silenziato</small><span class="symbol"><small>✅</small></span></p></div><p>Forza altoparlante fa suonare l&#39;allarme sul telefono anche quando usi altri altoparlanti (ad esempio Bluetooth)</p><div class="admonition xdripitem"><p class="admonition-title"><small>Forza altoparlante</small><span class="symbol"><small>✅</small></span></p></div><p>Attiva anche Vibrazione attiva la vibrazione del telefono</p><div class="admonition xdripitem"><p class="admonition-title"><small>Attiva anche Vibrazione</small><span class="symbol"><small>✅</small></span></p></div><p>Disabilita Allarme lo disattiva completamente: apparirà barrato nella Lista Allarmi</p><div class="admonition xdripitem"><p class="admonition-title"><small>Disabilita Allarme</small><span class="symbol"><small>☐</small></span></p></div><p><span style="background-color:gray;color:white;"> ALLARME TEST </span> fa suonare questo avviso</p><p><span style="background-color:gray;color:white;"> SALVA ALLARME </span> salva questo avviso nuovo o modificato</p><p><span style="background-color:gray;color:white;"> RIMUOVI ALLARME </span> elimina questo avviso</p><p><span style="background-color:gray;color:white;"> SOSPENDI ALLARME PRIMA CHE SI ATTIVI </span> ti permette di evitare che l&#39;avviso scatti: ad esempio, se hai già trattato un&#39;ipoglicemia o un&#39;iperglicemia prevista e sai che la glicemia cambierà comunque, puoi evitare di sentire l&#39;allarme per il tempo che vuoi.</p><h3 id="glucose-alerts-settings" tabindex="-1">Impostazioni Allarmi Glicemia <a class="header-anchor" href="#glucose-alerts-settings" aria-label="Permalink to &quot;Impostazioni Allarmi Glicemia {#glucose-alerts-settings}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Impostazioni Allarmi Glicemia</p></div><h5 id="alert-volume-profile" tabindex="-1">Profilo Volume ALLARMI <a class="header-anchor" href="#alert-volume-profile" aria-label="Permalink to &quot;Profilo Volume ALLARMI {#alert-volume-profile}&quot;">​</a></h5><p>Puoi personalizzare il volume dei tuoi avvisi</p><div class="admonition xdripitem"><p class="admonition-title">Profilo Volume ALLARMI</p><p> Alto <span style="float:right;">○ </span>   <br>  Medio <span style="float:right;">○ </span>   <br>  Crescente <span style="float:right;">● </span>   <br>  Solo vibrazione <span style="float:right;">○ </span>   <br>  Silenzioso <span style="float:right;">○ </span>   </p></div><p>Il volume Crescente è consigliato se non vuoi che l&#39;allarme suoni subito a tutto volume (utile di notte). Puoi anche <a href="#delay-ascending-volume">ritardare</a> il volume crescente per filtrare le letture disturbate e limitare il volume massimo.</p><p>Dal <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.10.16" target="_blank" rel="noreferrer">16 ottobre 2026</a>, selezionando Solo vibrazione o Silenzioso ti viene chiesta una conferma: con questi profili gli avvisi non emettono alcun suono, nemmeno quelli con Ignora la modalità silenziosa attivato. Il profilo viene cambiato solo se confermi.</p><h5 id="audio-focus" tabindex="-1">Focus Audio <a class="header-anchor" href="#audio-focus" aria-label="Permalink to &quot;Focus Audio {#audio-focus}&quot;">​</a></h5><p>Focus Audio ti permette di decidere come gestire gli altri suoni quando scatta un allarme o un avviso di xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Focus Audio</p><p>Scegli cosa fare con altre app durante la riproduzione degli avvisi e la regolazione dei livelli di volume del sistema</p></div><p>Puoi abbassare automaticamente il volume, mettere in pausa le altre app che riproducono suoni (come i lettori multimediali) o mettere in pausa tutti gli altri suoni, per concentrarti meglio sul suono di xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Focus Audio</p><p> Non regolare il volume delle altre app <span style="float:right;">● </span>   <br>  Abbassa il volume delle altre app <span style="float:right;">○ </span>   <br>  Pausa le altre applicazioni in riproduzione audio <span style="float:right;">○ </span>   <br>  Sospendi tutti gli altri suoni <span style="float:right;">○ </span>   </p></div><h5 id="smart-snoozing" tabindex="-1">Sospendi Allarmi Smart <a class="header-anchor" href="#smart-snoozing" aria-label="Permalink to &quot;Sospendi Allarmi Smart {#smart-snoozing}&quot;">​</a></h5><h5 id="smart-alerting" tabindex="-1">Avviso SMART <a class="header-anchor" href="#smart-alerting" aria-label="Permalink to &quot;Avviso SMART {#smart-alerting}&quot;">​</a></h5><p>Sospendi Allarmi Smart e Avviso SMART evitano che l&#39;avviso scatti o si ripeta se la glicemia sta andando nella direzione giusta (verso l&#39;alto per gli avvisi di glicemia bassa e verso il basso per quelli di glicemia alta). Le soglie per riconoscere una variazione sufficiente nella direzione giusta sono:</p><ul><li>Variazione superiore a +4 mg/dL in 5 minuti dall&#39;avviso di glicemia bassa</li><li>Variazione superiore a -1 mg/dL in 5 minuti dall&#39;avviso di glicemia alta</li></ul><div class="admonition xdripitem"><p class="admonition-title">Sospendi Allarmi Smart <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Continua a sospendere l&#39;allarme se il valore glicemico si muove nella giusta direzione</p></div><div class="admonition xdripitem"><p class="admonition-title">Avviso SMART <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Allarme non attivato se il valore glicemico si muove nella giusta direzione</p></div><h5 id="dont-alarm-during-phone-calls" tabindex="-1">Allarme disattivato durante le chiamate <a class="header-anchor" href="#dont-alarm-during-phone-calls" aria-label="Permalink to &quot;Allarme disattivato durante le chiamate {#dont-alarm-during-phone-calls}&quot;">​</a></h5><p>Gli allarmi non suonano se scattano durante una telefonata.</p><div class="admonition xdripitem"><p class="admonition-title">Allarme disattivato durante le chiamate <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Allarmi silenziati durante le chiamate telefoniche</p></div><h5 id="buttons-silence-alarms" tabindex="-1">Silenzia allarmi con tasti di volume <a class="header-anchor" href="#buttons-silence-alarms" aria-label="Permalink to &quot;Silenzia allarmi con tasti di volume {#buttons-silence-alarms}&quot;">​</a></h5><p>Silenzia allarmi con tasti di volume è un modo rapido per sospendere gli allarmi premendo semplicemente il tasto volume su o giù.</p><div class="admonition xdripitem"><p class="admonition-title">Silenzia allarmi con tasti di volume <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Premendo il pulsante di volume silenzierà un allarme attivo quando nell&#39;app</p></div><h5 id="alert-buttons" tabindex="-1">Pulsanti di avviso <a class="header-anchor" href="#alert-buttons" aria-label="Permalink to &quot;Pulsanti di avviso {#alert-buttons}&quot;">​</a></h5><p>Pulsanti di avviso aggiunge un pulsante di azione nella vista estesa della notifica dell&#39;avviso.</p><div class="admonition xdripitem"><p class="admonition-title">Pulsanti di avviso <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Mostra i pulsanti azione (come Snooze) nelle notifiche di avviso</p></div><img src="'+v+'" style="zoom:75%;"><img src="'+g+'" style="zoom:75%;"><h5 id="start-snoozed" tabindex="-1">Inizio Ritardato <a class="header-anchor" href="#start-snoozed" aria-label="Permalink to &quot;Inizio Ritardato {#start-snoozed}&quot;">​</a></h5><p>Inizio Ritardato applica il ritardo di sospensione prima di far scattare l&#39;allarme. Assicurati che il ritardo <code>Sospensione Allarmi di Default</code> dell&#39;allarme sia adeguato.</p><div class="admonition xdripitem"><p class="admonition-title">Inizio Ritardato <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Gli avvisi iniziano sospesi e devono persistere per un po &#39;per suonare</p></div><h5 id="wake-screen" tabindex="-1">Attivazione schermo <a class="header-anchor" href="#wake-screen" aria-label="Permalink to &quot;Attivazione schermo {#wake-screen}&quot;">​</a></h5><p>Attiva lo schermo durante gli avvisi.</p><div class="admonition xdripitem"><p class="admonition-title">Attivazione schermo<img src="'+o+'" style="zoom:75%;"></p><p> Attiva lo schermo durante gli avvisi. Potrebbe sbloccare i dispositivi che non hanno il blocco dello schermo abilitato.</p></div><h5 id="use-camera-light" tabindex="-1">Usa Torcia <a class="header-anchor" href="#use-camera-light" aria-label="Permalink to &quot;Usa Torcia {#use-camera-light}&quot;">​</a></h5><p>Fa lampeggiare il flash della fotocamera posteriore durante gli avvisi (quando il telefono è in carica).</p><div class="admonition xdripitem"><p class="admonition-title">Usa Torcia<img src="'+o+'" style="zoom:75%;"></p><p> Lampeggia la torcia durante gli avvisi quando collegato a un caricabatterie</p></div><h5 id="shortcut-to-bg-level-alerts" tabindex="-1">Scorciatoia allarmi glicemia <a class="header-anchor" href="#shortcut-to-bg-level-alerts" aria-label="Permalink to &quot;Scorciatoia allarmi glicemia {#shortcut-to-bg-level-alerts}&quot;">​</a></h5><p>Puoi aggiungere una voce di scorciatoia ad <code>Allarmi di livello</code> nel menu principale di xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Scorciatoia allarmi glicemia<img src="'+i+'" style="zoom:75%;"></p><p> Crea una scorciatoia dallo schermo principale alle impostazioni di allarmi glicemia</p></div><h5 id="suppress-alerts-if-missed-readings" tabindex="-1">Eliminare gli avvisi in caso di Letture Mancanti <a class="header-anchor" href="#suppress-alerts-if-missed-readings" aria-label="Permalink to &quot;Eliminare gli avvisi in caso di Letture Mancanti {#suppress-alerts-if-missed-readings}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Eliminare gli avvisi in caso di Letture Mancanti</p></div><p>Gli avvisi di livello restano attivi anche quando non c&#39;è segnale (ad esempio durante il cambio del sensore, o per un follower senza rete). Questa opzione ti permette di eliminarli. Se usi questa funzione, assicurati di avere attivato un avviso di letture mancanti.</p><div class="admonition xdripitem"><p class="admonition-title">Eliminare gli avvisi in caso di Letture Mancanti <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Sopprimi gli allarmi attivi e silenziati dopo un periodo predefinito di letture perse</p></div><p>Puoi definire dopo quanti minuti vuoi che gli avvisi si fermino.</p><div class="admonition xdripitem"><p class="admonition-title">Sopprimi gli allarmi silenziati e attivi dopo .. minuti (minimo 10)</p><p> Sopprimi gli allarmi attivi e silenziati dopo un periodo predefinito di letture perse</p></div><h5 id="notification-channels" tabindex="-1">Canali di notifica <a class="header-anchor" href="#notification-channels" aria-label="Permalink to &quot;Canali di notifica {#notification-channels}&quot;">​</a></h5><p>Poiché Android 8.0 è ora la versione minima supportata, xDrip usa sempre i canali di notifica di Android per i tuoi avvisi. L&#39;impostazione che serviva ad attivarli è stata rimossa quando è terminato il supporto ad Android 7 (<a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12 luglio 2026</a>): i canali sono ora sempre attivi.</p><p>Dal <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 settembre 2026</a> xDrip crea solo quattro canali e riproduce da sé il suono e la vibrazione degli avvisi, invece di passare dal canale. I canali più vecchi vengono rimossi automaticamente.</p><div class="admonition xdripitem"><p class="admonition-title">Canali di notifica di xDrip</p><p> Allarmi Livello Glicemia<br>  Altri allarmi<br>  Generale<br>  Notifica persistente</p></div><p>Le impostazioni dei canali in Impostazioni Android / Notifiche / App / xDrip decidono solo se la notifica viene mostrata. Suono e vibrazione dipendono dalle impostazioni di xDrip: il <a href="#alert-volume-profile">profilo volume allarmi</a> e le opzioni Ignora la modalità silenziosa e Attiva anche Vibrazione di ogni avviso. Disattivare un canale nasconde la notifica ma non silenzia l&#39;avviso: per farlo, disattiva l&#39;avviso in xDrip.</p><h5 id="alert-priority" tabindex="-1">Priorità degli avvisi <a class="header-anchor" href="#alert-priority" aria-label="Permalink to &quot;Priorità degli avvisi {#alert-priority}&quot;">​</a></h5><p>Dal <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 settembre 2026</a>, quando due avvisi si sovrappongono vince il più importante: interrompe il suono e la vibrazione di un avviso meno importante già in corso, e un avviso meno importante non può interrompere uno più importante che sta ancora suonando. Questo riguarda solo suono e vibrazione, non la sospensione o la chiusura. Dalla priorità più alta alla più bassa:</p><ol><li>Letture mancanti</li><li>Glicemia bassa</li><li>Glicemia alta persistente</li><li>Glicemia alta</li><li>Glicemia bassa prevista</li><li>Glicemia in discesa o in salita rapida</li><li>Scadenza del sensore</li><li>Allarme BlueReader</li><li>Avvisi di valori sporchi (rumore)</li><li>Promemoria</li><li>Riavvio della sessione OB1</li><li>Altre notifiche</li></ol><p>Dal <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.10.09" target="_blank" rel="noreferrer">9 ottobre 2026</a>, quando il telefono è in modalità silenziosa (o è selezionato il <a href="#alert-volume-profile">profilo volume allarmi</a> Silenzioso) e Ignora la modalità silenziosa è disattivato, gli avvisi fino a Glicemia in discesa o in salita rapida scrivono comunque una voce nel log indicando che non è stato riprodotto alcun suono, così puoi vedere in seguito che un avviso è scattato.</p><h5 id="ascending-volume-settings" tabindex="-1">Impostazioni Volume Crescente <a class="header-anchor" href="#ascending-volume-settings" aria-label="Permalink to &quot;Impostazioni Volume Crescente {#ascending-volume-settings}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Impostazioni Volume Crescente</p></div><h5 id="delay-ascending-volume" tabindex="-1">Ritardo Volume Crescente <a class="header-anchor" href="#delay-ascending-volume" aria-label="Permalink to &quot;Ritardo Volume Crescente {#delay-ascending-volume}&quot;">​</a></h5><p>Puoi ritardare l&#39;inizio dell&#39;avviso a volume crescente senza ritardare la vibrazione, che inizia non appena l&#39;avviso scatta.</p><div class="admonition xdripitem"><p class="admonition-title">Ritardo Volume Crescente<img src="'+e+'" style="zoom:75%;"></p><p> Per il profilo di volume crescente, ritarda di 3 minuti l&#39;inizio del suono di allarme. La vibrazione (se abilitata) inizia non appena l&#39;avviso si attiva, indipendentemente da questa impostazione.</p></div><h5 id="ascend-to-medium" tabindex="-1">Aumenta fino a medio <a class="header-anchor" href="#ascend-to-medium" aria-label="Permalink to &quot;Aumenta fino a medio {#ascend-to-medium}&quot;">​</a></h5><p>Puoi limitare il volume massimo di avvisi e allarmi a volume crescente al livello medio invece che al massimo.</p><div class="admonition xdripitem"><p class="admonition-title">Aumenta fino a medio<img src="'+i+'" style="zoom:75%;"></p><p> Se abilitato, il volume aumenterà fino al volume medio invece del volume massimo</p></div><h3 id="calibration-alerts" tabindex="-1">Avvisi di calibrazione <a class="header-anchor" href="#calibration-alerts" aria-label="Permalink to &quot;Avvisi di calibrazione {#calibration-alerts}&quot;">​</a></h3><p>Se il tuo sensore richiede una calibrazione periodica, puoi configurare xDrip per avvisarti quando è il momento di calibrare.</p><p>Puoi impostare l&#39;intervallo tra le calibrazioni, il suono da riprodurre, ecc.</p><div class="admonition xdrip"><p class="admonition-title">Avvisi di calibrazione</p></div><div class="admonition xdripitem"><p class="admonition-title">Avvisi di calibrazione<img src="'+o+'" style="zoom:75%;"></p><p> Avvisa quando è richiesta una calibrazione</p></div><div class="admonition xdripitem"><p class="admonition-title">Ore tra calibrazione</p><p> Quante ore tra le richieste di calibrazione</p></div><div class="admonition xdripitem"><p class="admonition-title">Avviso di Richiesta Calibrazione</p><p> Default</p></div><div class="admonition xdripitem"><p class="admonition-title">Ignora la modalità silenziosa<img src="'+s+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Anche quando sotto carica<img src="'+s+'" style="zoom:75%;"></p><p> Deseleziona per non chiedere calibrazioni quando il telefono è in carica</p></div><div class="admonition xdripitem"><p class="admonition-title">Ripetizione di allarmi<img src="'+s+'" style="zoom:75%;"></p><p> Continua ad avvisare se non viene eseguita la calibrazione</p></div><div class="admonition xdripitem"><p class="admonition-title">Minuti per ripetizione allarme</p><p> 20</p></div><h5 id="initial-alert" tabindex="-1">Avviso iniziale <a class="header-anchor" href="#initial-alert" aria-label="Permalink to &quot;Avviso iniziale {#initial-alert}&quot;">​</a></h5><p>L&#39;avviso di calibrazione iniziale si usa all&#39;avvio di un sensore che richiede una calibrazione iniziale: scatta quando sono disponibili abbastanza letture valide per calibrare.</p><div class="admonition xdripitem"><p class="admonition-title">Avviso iniziale<img src="'+l+'" style="zoom:75%;"></p><p> Suona quando viene richiesta la calibrazione iniziale</p></div><h3 id="missed-reading-alert" tabindex="-1">Allarme Mancata Ricezione Segnale <a class="header-anchor" href="#missed-reading-alert" aria-label="Permalink to &quot;Allarme Mancata Ricezione Segnale {#missed-reading-alert}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Allarme Mancata Ricezione Segnale</p></div><p>Se ti affidi a xDrip per gli avvisi di glicemia bassa e alta, è essenziale assicurarti che riceva davvero le letture. Per questo, se non hai altri allarmi, attiva questa funzione per la tua sicurezza.</p><p>La configurazione è simile a quella degli <a href="#glucose-level-alerts-list">avvisi di livello glicemia</a>. <strong>Il suono dell&#39;allarme va definito in Altri Allarmi</strong> (vedi <a href="#alert-preferences">sotto</a>). Per provarlo, metti il telefono in modalità aereo finché non scatta.</p><div class="admonition xdrip"><p class="admonition-title">☰ Configurare Letture Mancate</p><p> <small>✅ Abilita Avviso Lettura Mancata</small><br>  <small>Avviso se non ci sono dati ricevuti in:</small><br>  <small><u> 30 </u> minuti</small><br>  <small>Seleziona Tono Allarme:</small><br>  <small>✅ Tutto il giorno</small></p><p> <small>Attesa prima di ripetere lo stesso avviso dopo averlo silenziato:</small><br>  <small><u> 20 </u> minuti</small><br>  <small>☐ Ripeti allarmi prima della fine silenziamento</small><br>  <small>Tempo prima di ripetere l&#39;avviso:</small><br>  <small><u> 60 </u> secondi</small><br>  <small>☐ Ignora la modalità silenziosa</small></p></div><h3 id="other-alerts" tabindex="-1">Altri Allarmi <a class="header-anchor" href="#other-alerts" aria-label="Permalink to &quot;Altri Allarmi {#other-alerts}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Altri Allarmi</p></div><h4 id="noisy-readings" tabindex="-1">Letture rumorose <a class="header-anchor" href="#noisy-readings" aria-label="Permalink to &quot;Letture rumorose {#noisy-readings}&quot;">​</a></h4><div class="admonition xdripitem"><p class="admonition-title"><small>LETTURE RUMOROSE</small></p></div><p>Se attivi questa funzione e il tuo sensore la supporta, puoi configurare un avviso per le letture rumorose (disturbate).</p><div class="admonition xdripitem"><p class="admonition-title">Avvisi di Valori sporchi (rumore)<img src="'+i+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Avviso dopo x minuti di valori rumorosi</p><p> 90</p></div><div class="admonition xdripitem"><p class="admonition-title">Silenzia allarme</p><p> Numero di minuti prima di ripetere lo stesso allarme dopo essere stato silenziato.</p></div><div class="admonition xdripitem"><p class="admonition-title">Ripeti allarmi prima della fine silenziamento<img src="'+i+'" style="zoom:75%;"></p><p> Ripeti allarme si non silenziato prima</p></div><div class="admonition xdripitem"><p class="admonition-title">Tempo prima di ripetere l&#39;allarme</p><p> Numero di SECONDI prima di ripetere lo stesso allarme.</p></div><h4 id="falling-or-rising-bg" tabindex="-1">Glicemia in discesa o in salita <a class="header-anchor" href="#falling-or-rising-bg" aria-label="Permalink to &quot;Glicemia in discesa o in salita {#falling-or-rising-bg}&quot;">​</a></h4><div class="admonition xdripitem"><p class="admonition-title"><small>GLICEMIA IN SALITA/DISCESA</small></p></div><p>Puoi anche configurare avvisi per le variazioni rapide della glicemia e definire il valore di variazione al minuto che li fa scattare. Ad esempio 3 al minuto significa 15 mg/dL (0,85 mmol/L) ogni 5 minuti.</p><div class="admonition xdripitem"><p class="admonition-title">Glicemia in discesa veloce<img src="'+i+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Soglia di discesa</p><p> 3 mg/dl/min (0.17 mmol/l/min)</p></div><div class="admonition xdripitem"><p class="admonition-title">Glicemia in salita rapida<img src="'+i+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Soglia di salita</p><p> 3 mg/dl/min (0.17 mmol/l/min)</p></div><h5 id="alert-preferences" tabindex="-1">Impostazioni allarmi per questi avvisi <a class="header-anchor" href="#alert-preferences" aria-label="Permalink to &quot;Impostazioni allarmi per questi avvisi {#alert-preferences}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title"><small>IMPOSTAZIONI ALLARMI PER QUESTI AVVISI</small></p></div><p>Gli avvisi qui sopra e <strong>anche le Letture mancanti</strong> usano il suono e la vibrazione definiti qui sotto.<br> Dal <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 settembre 2026</a> è xDrip stesso a riprodurli: i <a href="#notification-channels">canali di notifica</a> non controllano più suono e vibrazione. Anche i <a href="#alert-volume-profile">profili volume allarmi</a> Solo vibrazione e Silenzioso si applicano a questi avvisi. Quando il telefono è in modalità vibrazione viene riprodotta solo la vibrazione, e in modalità silenziosa non viene riprodotto nulla a meno che Ignora la modalità silenziosa non sia attivato.</p><div class="warning custom-block"><p class="custom-block-title">Assicurati di provare l&#39;allarme</p><p>È una funzione importante per dormire tranquillo. Riduci il periodo delle letture mancanti e metti il telefono in modalità aereo (senza Wi-Fi) per forzare l&#39;allarme a suonare.</p></div><div class="admonition xdripitem"><p class="admonition-title">Suoneria di allarme</p><p> Default</p></div><p>Default è il suono di xDrip: l&#39;allarme di xDrip per le letture mancanti, un suono di notifica più delicato per gli altri avvisi. Usa SCEGLI FILE per scegliere una suoneria del telefono o un tuo file. Dal <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.25" target="_blank" rel="noreferrer">25 settembre 2026</a> il suono più delicato viene usato anche quando è selezionata la suoneria <em>Predefinita</em> del telefono, comprese le installazioni aggiornate da prima del 9 settembre 2026 che non hanno mai cambiato questa impostazione: gli avvisi di letture non chiare, salita, discesa e simili non suonano più come l&#39;allarme di glicemia.</p><div class="admonition xdripitem"><p class="admonition-title">Ignora la modalità silenziosa<img src="'+e+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Attiva anche Vibrazione<img src="'+e+'" style="zoom:75%;"></p></div><h3 id="extra-alerts" tabindex="-1">Allarmi Extra <a class="header-anchor" href="#extra-alerts" aria-label="Permalink to &quot;Allarmi Extra {#extra-alerts}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Allarmi Extra (xDrip+)</p></div><h5 id="persistent-high-alert" tabindex="-1">Allarme per VALORI ALTI Persistenti <a class="header-anchor" href="#persistent-high-alert" aria-label="Permalink to &quot;Allarme per VALORI ALTI Persistenti {#persistent-high-alert}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Allarme per VALORI ALTI Persistenti</p></div><p>Invece di un avviso di glicemia alta che scatta non appena la glicemia raggiunge il valore di soglia, puoi configurare un avviso di glicemia alta persistente, che scatta solo quando la glicemia resta sopra un valore impostato per più di un certo tempo. Per far scattare questo avviso puoi usare il <a href="./settings.html#glucose-units">Valore Massimo</a> di xDrip oppure un valore scelto da te.</p><div class="admonition xdripitem"><p class="admonition-title">Abilita<img src="'+o+'" style="zoom:75%;"></p><p> Allarme se persistono valori ALTI</p></div><div class="admonition xdripitem"><p class="admonition-title">Soglia: Valore Alto<img src="'+l+'" style="zoom:75%;"></p><p> Se abilitato, la soglia è il valore di glicemia alta.<br>  Quando disabilitato, la soglia è il valore specificato sotto.</p></div><div class="admonition xdripitem"><p class="admonition-title">Soglia</p><p> 170 mg/dl</p></div><div class="admonition xdripitem"><p class="admonition-title">per più di (minuti)</p><p> 60</p></div><div class="admonition xdripitem"><p class="admonition-title">Ripeti ogni (minuti)</p><p> 20</p></div><div class="admonition xdripitem"><p class="admonition-title">Allarme per VALORI ALTI Persistenti</p><p> Scegliere il suono usato per allarme valore ALTO persistente.</p></div><div class="admonition xdripitem"><p class="admonition-title">Ignora la modalità silenziosa<img src="'+i+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Attiva anche Vibrazione<img src="'+e+'" style="zoom:75%;"></p></div><h5 id="forecasted-low-alert" tabindex="-1">Allarme di previsione VALORE BASSO <a class="header-anchor" href="#forecasted-low-alert" aria-label="Permalink to &quot;Allarme di previsione VALORE BASSO {#forecasted-low-alert}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Allarme di previsione VALORE BASSO</p></div><p>Puoi impostare un allarme sul valore basso previsto. Questa funzione usa il <strong>momentum</strong> (estrapolazione della tendenza attuale della glicemia) e <strong>non</strong> le impostazioni di <a href="./predictions.html">previsione</a>. Il tempo della previsione di glicemia bassa (min) è il tempo entro il quale viene prevista una glicemia bassa (quello che di solito appare in giallo sulla schermata del grafico).</p><p>Lows Previsione mostra un messaggio sulla schermata di xDrip. Per far suonare un allarme quando è prevista una glicemia bassa, attiva Allarme Previsione Ragg. VALORE BASSO.</p><div class="admonition xdripitem"><p class="admonition-title">Lows Previsione<img src="'+l+'" style="zoom:75%;"></p><p> Estrapolare i dati per cercare di prevedere raggiungimento VALORE BASSO</p></div><div class="admonition xdripitem"><p class="admonition-title">Allarme Previsione Ragg. VALORE BASSO<img src="'+i+'" style="zoom:75%;"></p><p> Notifica quando il valore minimo previsto raggiunge la soglia</p></div><div class="admonition xdripitem"><p class="admonition-title">Soglia: Valore Basso<img src="'+l+'" style="zoom:75%;"></p><p> Se abilitato, la soglia è il valore di glicemia bassa.<br>  Quando disabilitato, la soglia è il valore specificato sotto.</p></div><div class="admonition xdripitem"><p class="admonition-title">Soglia</p><p> 70 mg/dl</p></div><div class="admonition xdripitem"><p class="admonition-title">Allarme previsione VALORE BASSO (minuti)</p><p> 40</p></div><div class="admonition xdripitem"><p class="admonition-title">Previsto a bassa emissione sonora</p><p> Scegli il suono per previsione ragg. VALORE BASSO</p></div><div class="admonition xdripitem"><p class="admonition-title">Ignora la modalità silenziosa<img src="'+i+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Attiva anche Vibrazione<img src="'+e+'" style="zoom:75%;"></p></div><p>Nell&#39;esempio qui sotto, se imposti Allarme previsione VALORE BASSO (minuti) a 50 minuti, l&#39;allarme scatterà. La linea rossa tratteggiata è la tendenza prevista della glicemia, estrapolata dalle misure precedenti.</p><img src="'+h+'" style="zoom:75%;"><h5 id="sensor-expiry-notifications" tabindex="-1">Notifiche Scadenza Sensore <a class="header-anchor" href="#sensor-expiry-notifications" aria-label="Permalink to &quot;Notifiche Scadenza Sensore {#sensor-expiry-notifications}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Notifiche Scadenza Sensore</p><p> Genera delle notifiche quando il sensore si avvicina alla scadenza.</p></div><div class="admonition xdripitem"><p class="admonition-title">Abilita<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Genera delle notifiche quando il sensore si avvicina alla scadenza.</p></div><p>Dal <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 settembre 2026</a> un follower mostra la stessa notifica quando arriva l&#39;avviso di scadenza del master, purché questa impostazione sia attivata anche sul follower e i trattamenti siano sincronizzati dal master. L&#39;avviso viene mostrato una volta per ogni avviso del sensore e viene ignorato se raggiunge il follower con più di 30 minuti di ritardo.</p><h5 id="follower-chime-new" tabindex="-1">Suoneria nuovo Follower <a class="header-anchor" href="#follower-chime-new" aria-label="Permalink to &quot;Suoneria nuovo Follower {#follower-chime-new}&quot;">​</a></h5><p>Dopo delle letture mancanti, una notifica suona quando arrivano nuovi dati dopo più di 20 minuti.</p><div class="admonition xdripitem"><p class="admonition-title">Suoneria nuovo Follower<img src="'+o+'" style="zoom:75%;"></p><p> Notifica se i dati arrivano dal master con un intervallo &gt; 20 minuti.</p></div><h2 id="snooze-alert" tabindex="-1">Sospendi Allarme <a class="header-anchor" href="#snooze-alert" aria-label="Permalink to &quot;Sospendi Allarme {#snooze-alert}&quot;">​</a></h2><div class="admonition xdrip"><p class="admonition-title"><img src="'+m+'" style="zoom:75%;"></p><p> Sospendi Allarme</p></div><p>Se non c&#39;è nessun avviso attivo, da questo menu puoi <strong>sospendere in anticipo</strong> gli avvisi in modo che non scattino per un certo tempo.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;">Sospendi Allarme</p><div style="text-align:center;"> Non esiste un allarme attivo</div><div style="background-color:gray;color:white;text-align:center;">  Disabilitare Allarmi raggiungimento VALORE BASSO </div><div style="background-color:gray;color:white;text-align:center;">  Disabilitare Allarmi raggiungimento VALORE ALTO </div><div style="background-color:gray;color:white;text-align:center;">  Disabilitare Tutti gli Allarmi </div></div><p>Ti verrà proposto un periodo di sospensione predefinito. Scorri su e giù per cambiarlo.</p><div class="admonition xdrip"><p class="admonition-title">Ritardo Allarme Predefinito</p><div style="background-color:darkgray;color:dimgray;text-align:center;">  50 minuti </div><div style="background-color:darkgray;color:black;text-align:center;">  60 minuti </div><div style="background-color:darkgray;color:dimgray;text-align:center;">  70 minuti </div></div><p>Quando scatta un avviso, vedrai la notifica nel pannello a discesa del telefono ed eventualmente sentirai il suono.</p><p>Puoi sospendere l&#39;avviso scorrendo la notifica; toccandola puoi personalizzarla ulteriormente.</p><img src="'+b+'" style="zoom:75%;"><p>Puoi accedere al menu di sospensione toccando la notifica oppure dal menu principale di xDrip, Sospendi Allarme.</p><p>A questo punto il menu di sospensione mostra anche l&#39;avviso attivo.<br> Toccando Sospendi Allarme lo sospendi per il periodo selezionato.</p>',185)),t("div",k,[a[1]||(a[1]=t("p",{class:"admonition-title"},[t("img",{src:n,style:{zoom:"75%"}}),p("Sospendi Allarme")],-1)),t("div",R,[c(d,null,{default:u(()=>[c(d,null,{default:u(()=>[...a[0]||(a[0]=[p("Sospendi Allarme",-1)])]),_:1})]),_:1})]),a[2]||(a[2]=r('<div style="background-color:dimgray;color:white;text-align:center;">  <div style="background-color:black;color:dimgray;text-align:center;">  20 minuti </div><div style="background-color:black;color:darkgray;text-align:center;">  30 minuti </div><div style="background-color:black;color:dimgray;text-align:center;">  40 minuti </div></div><p>L&#39;avviso attivo chiamato &quot;Night&quot; esiste. L&#39;avviso si riproporrà in 1:25:01 (0 minuti rimanenti)</p><div style="background-color:dimgray;color:white;text-align:center;">  Disabilitare Allarmi raggiungimento VALORE BASSO </div><div style="background-color:dimgray;color:white;text-align:center;">  Disabilitare Allarmi raggiungimento VALORE ALTO </div><div style="background-color:dimgray;color:white;text-align:center;">  Disabilitare Tutti gli Allarmi </div>',5))]),a[4]||(a[4]=r('<h5 id="all-alerts-currently-disabled" tabindex="-1">TUTTI GLI ALLARMI SONO DISABILITATI <a class="header-anchor" href="#all-alerts-currently-disabled" aria-label="Permalink to &quot;TUTTI GLI ALLARMI SONO DISABILITATI {#all-alerts-currently-disabled}&quot;">​</a></h5><p>Se sospendi in anticipo (disattivi) tutti gli avvisi, vedrai questo messaggio di avvertimento.</p><img src="'+f+'" style="zoom:75%;"><p>Per rimuoverlo devi riattivare gli avvisi.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;">Sospendi Allarme</p><div style="text-align:center;"> Tutti gli Allarmi disattivati per 15:09:12</div><div style="background-color:gray;color:white;text-align:center;">  Riattiva tutti gli Allarmi </div></div><br><h2 id="visible-alert-notification" tabindex="-1">Notifica visibile dell&#39;avviso <a class="header-anchor" href="#visible-alert-notification" aria-label="Permalink to &quot;Notifica visibile dell&#39;avviso {#visible-alert-notification}&quot;">​</a></h2><p>Disponibile da Android 8 in poi.</p><p>Quando scatta un avviso, lo vedi nel pannello a discesa delle notifiche.</p><img src="'+A+'" style="zoom:75%;"><p>Scorrendolo lo sospendi, toccandolo apri un menu di preferenze.<br> La consegna silenziosa riguarda solo la notifica Android. Dal <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 settembre 2026</a> il suono e la vibrazione dell&#39;avviso sono riprodotti da xDrip e seguono le impostazioni degli avvisi di xDrip, non il <a href="#notification-channels">canale di notifica</a>.</p><img src="'+z+'" style="zoom:75%;"><p>Dallo stesso menu puoi tornare alla consegna con avviso.</p><img src="'+x+'" style="zoom:75%;"><p>Impostazioni ti porta alle impostazioni delle notifiche del telefono.</p><img src="'+S+'" style="zoom:75%;"><p>Puoi anche disattivare completamente i <a href="#notification-channels">canali di notifica</a> di xDrip. Questo nasconde le notifiche ma non ferma il suono dell&#39;avviso.</p><img src="'+y+'" style="zoom:75%;"><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',19))])}const j=q(I,[["render",T]]);export{$ as __pageData,j as default};
